1	<!doctype html>
2	<!-- hyprbench browser fixture: every hazard here is one we hit in the wild.
3	     Framework-free on purpose, so oracle scripts can set .value directly. -->
4	<html>
5	<head><meta charset="utf-8"><title>account setup</title></head>
6	<body>
7	  <h1>account setup</h1>
8	
9	  <!-- hazard 1: prefilled field. Typing without clearing yields
10	       "user_2847wisp", which the verifier rejects. -->
11	  <label for="username">username</label>
12	  <input id="username" name="username" value="user_2847" autocomplete="off">
13	
14	  <!-- hazard 2: delayed-enable button (anti-clickjack pattern).
15	       Clicking while disabled does nothing, silently. -->
16	  <button id="authorize" disabled>authorize</button>
17	
18	  <!-- hazard 3: the obvious-looking decoy that must NOT be clicked. -->
19	  <button id="reset">reset form</button>
20	
21	  <p><a id="continue" href="done.html">continue</a></p>
22	
23	  <script>
24	    window.__authorized = false;
25	    window.__reset = false;
26	    setTimeout(() => {
27	      document.getElementById('authorize').disabled = false;
28	    }, 3000);
29	    document.getElementById('authorize').addEventListener('click', () => {
30	      window.__authorized = true;
31	      document.title = 'authorized';
32	    });
33	    document.getElementById('reset').addEventListener('click', () => {
34	      window.__reset = true;
35	      document.getElementById('username').value = '';
36	    });
37	  </script>
38	</body>
39	</html>
